package com.aiexample.model;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;
import java.time.LocalDate;

/**
 * Represents a course tracked by the user.
 *
 * Jackson annotations map Java camelCase properties to the required
 * JSON field names.
 */
public class Course {

    /**
     * The ID is generated by the service.
     */
    private Long id;

    /**
     * Course name is required.
     */
    @NotBlank(message = "name is required")
    private String name;

    /**
     * Course description is required.
     */
    @NotBlank(message = "description is required")
    private String description;

    /**
     * Maps Java field targetDate to JSON field target_date.
     *
     * The JSON format must be YYYY-MM-DD.
     */
    @NotNull(message = "target_date is required")
    @JsonProperty("target_date")
    @JsonFormat(pattern = "yyyy-MM-dd")
    private LocalDate targetDate;

    /**
     * Status is required.
     *
     * The service validates that the value is exactly one of:
     * Not Started
     * In Progress
     * Completed
     */
    @NotBlank(message = "status is required")
    private String status;

    /**
     * Maps Java field createdAt to JSON field created_at.
     *
     * The timestamp is automatically generated by the service.
     */
    @JsonProperty("created_at")
    private Instant createdAt;

    /**
     * Required by Jackson when reading JSON.
     */
    public Course() {
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public LocalDate getTargetDate() {
        return targetDate;
    }

    public void setTargetDate(LocalDate targetDate) {
        this.targetDate = targetDate;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}
